/**
 * EDITH Router Classifier
 * Classifies incoming Telegram updates into discrete execution routes.
 */
const items = $input.all();
const results = [];

for (const item of items) {
  const json = item.json;

  // 1. Check for Callback Query (Inline keyboard buttons)
  if (json.callback_query) {
    const cb = json.callback_query;
    results.push({
      json: {
        route: 'callback',
        update_id: json.update_id,
        chat_id: cb.message?.chat?.id || cb.from?.id,
        message_id: cb.message?.message_id,
        callback_query_id: cb.id,
        callback_data: cb.data || '',
        from_id: cb.from?.id,
        from_username: cb.from?.username || '',
        from_name: [cb.from?.first_name, cb.from?.last_name].filter(Boolean).join(' '),
        from: {
          id: cb.from?.id,
          username: cb.from?.username || '',
          name: [cb.from?.first_name, cb.from?.last_name].filter(Boolean).join(' ')
        }
      }
    });
    continue;
  }

  // Extract standard message
  const msg = json.message || json.channel_post || json.edited_message;
  if (!msg) {
    results.push({
      json: {
        route: 'fallback',
        update_id: json.update_id,
        reason: 'no_message_found'
      }
    });
    continue;
  }

  const chatId = msg.chat?.id;
  const messageId = msg.message_id;
  const text = (msg.text || msg.caption || '').trim();
  const from = msg.from || {};
  const fromUser = {
    id: from.id,
    username: from.username || '',
    name: [from.first_name, from.last_name].filter(Boolean).join(' ')
  };
  const messageDate = msg.date || Math.floor(Date.now() / 1000);

  // 2. Check for Reply to Bot (Clarification responses)
  if (msg.reply_to_message && msg.reply_to_message.from && msg.reply_to_message.from.is_bot) {
    results.push({
      json: {
        route: 'reply',
        chat_id: chatId,
        message_id: messageId,
        message_date: messageDate,
        reply_to_message_id: msg.reply_to_message.message_id,
        reply_to_text: msg.reply_to_message.text || '',
        text: text,
        from: fromUser
      }
    });
    continue;
  }

  // 3. Check for .txt document upload
  if (msg.document) {
    const doc = msg.document;
    const isTxt = doc.mime_type === 'text/plain' || (doc.file_name && doc.file_name.toLowerCase().endsWith('.txt'));
    results.push({
      json: {
        route: 'doc_txt',
        chat_id: chatId,
        message_id: messageId,
        message_date: messageDate,
        file_id: doc.file_id,
        file_name: doc.file_name || (isTxt ? 'transcript.txt' : 'file'),
        file_size: doc.file_size || 0,
        mime_type: doc.mime_type || (isTxt ? 'text/plain' : 'application/octet-stream'),
        caption: text,
        from: fromUser
      }
    });
    continue;
  }

  // 4. Check for recognized slash commands
  const commandMatch = text.match(/^\/(start|help|register|tasks|update|done|assign|deadline|ask)(?:@\w+)?(?:\s+([\s\S]*))?$/i);
  if (commandMatch) {
    const command = commandMatch[1].toLowerCase();
    const args = (commandMatch[2] || '').trim();
    results.push({
      json: {
        route: 'command',
        chat_id: chatId,
        message_id: messageId,
        message_date: messageDate,
        command: command,
        command_args: args,
        raw_text: text,
        from: fromUser
      }
    });
    continue;
  }

  // 5. Check for transcript text (>300 chars or /upload_meeting)
  if (text.startsWith('/upload_meeting') || text.length > 300) {
    const cleanText = text.replace(/^\/upload_meeting(?:@\w+)?\s*/i, '').trim();
    results.push({
      json: {
        route: 'transcript_text',
        chat_id: chatId,
        message_id: messageId,
        message_date: messageDate,
        text: cleanText,
        text_length: cleanText.length,
        from: fromUser
      }
    });
    continue;
  }

  // 5b. Check for non-command questions in private chat (route to NL query)
  const isPrivateChat = typeof chatId === 'number' ? chatId > 0 : !String(chatId).startsWith('-');
  if (isPrivateChat && (text.endsWith('?') || /^(what|which|who|where|when|why|how|is|are|can|show)\b/i.test(text))) {
    results.push({
      json: {
        route: 'command',
        chat_id: chatId,
        message_id: messageId,
        message_date: messageDate,
        command: 'ask',
        command_args: text,
        raw_text: text,
        from: fromUser
      }
    });
    continue;
  }

  // 6. Fallback route for all other inputs
  results.push({
    json: {
      route: 'fallback',
      chat_id: chatId,
      message_id: messageId,
      message_date: messageDate,
      text: text,
      from: fromUser
    }
  });
}

return results;

/**
 * EDITH Member Registration (code-nodes/register_member.js)
 * 
 * Handles /register <your name>:
 * - Extracts sender's name, telegram_username, telegram_id, and chat_id
 * - Upserts in Members Google Sheets tab
 * - Emits confirmation: "Registered. EDITH will now send your reminders directly."
 */

function processRegisterMember(items, existingMembers = []) {
  const results = [];

  for (const item of items) {
    const json = item.json;

    const fromUser = json.from || {};
    const chatId = String(json.chat_id || fromUser.id || '');
    const telegramId = String(fromUser.id || '');
    const telegramUsername = (fromUser.username || '').replace(/^@/, '');
    const fallbackName = [fromUser.first_name, fromUser.last_name].filter(Boolean).join(' ') || telegramUsername || 'Team Member';

    // Extract name from command args: /register <your name>
    const text = (json.text || json.raw_text || '').trim();
    const commandArgs = (json.command_args || text.replace(/^\/register(?:@\w+)?\s*/i, '')).trim();
    const registeredName = commandArgs || fallbackName;

    // Check if member already exists in Members tab (match by telegram_id or case-insensitive name)
    const existing = existingMembers.find(m => 
      (m.telegram_id && String(m.telegram_id) === telegramId) ||
      (m.name && m.name.trim().toLowerCase() === registeredName.toLowerCase())
    );

    const memberRecord = {
      name: registeredName,
      telegram_username: telegramUsername,
      telegram_id: telegramId,
      chat_id: chatId
    };

    results.push({
      json: {
        chat_id: chatId,
        is_update: Boolean(existing),
        member_record: memberRecord,
        reply_message: 'Registered. EDITH will now send your reminders directly.'
      }
    });
  }

  return results;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    processRegisterMember
  };
}

if (typeof $input !== 'undefined') {
  let membersList = [];
  try {
    if (typeof $ !== 'undefined') {
      membersList = $('Read Members Tab').all().map(i => i.json);
    }
  } catch (e) {
    membersList = [];
  }

  return processRegisterMember($input.all(), membersList);
}
